"""One-off: write verified favicon PNGs from browser-verified data URLs,
then build a PNG-in-ICO favicon.ico. Temporary helper — deleted after use."""
import base64, struct

PNGS = {
    "favicon-16.png": "",
    "favicon-32.png": "",
    "favicon-48.png": "",
}

APPLE_180 = ""

def png_size(data: bytes):
    w = struct.unpack(">I", data[16:20])[0]
    h = struct.unpack(">I", data[20:24])[0]
    return w, h

def main():
    pngs = {}
    for name, b64 in PNGS.items():
        data = base64.b64decode(b64)
        assert data[:8] == b"\x89PNG\r\n\x1a\n", f"{name}: not a PNG"
        w, h = png_size(data)
        with open(name, "wb") as f:
            f.write(data)
        pngs[name] = (w, h, data)
        print(f"wrote {name}  {w}x{h}  {len(data)} bytes")

    apple = base64.b64decode(APPLE_180)
    assert apple[:8] == b"\x89PNG\r\n\x1a\n"
    with open("apple-touch-icon.png", "wb") as f:
        f.write(apple)
    print(f"wrote apple-touch-icon.png  {png_size(apple)[0]}x{png_size(apple)[1]}  {len(apple)} bytes")

    # Build a valid .ico embedding the 32px PNG (PNG-in-ICO, widely supported).
    w, h, png = pngs["favicon-32.png"]
    header = struct.pack("<HHHHHHHH", 0, 1, 1, w % 256, h % 256, 0, 0, 32, 0)
    entry = struct.pack("<I", len(png)) + struct.pack("<I", 22)
    with open("favicon.ico", "wb") as f:
        f.write(header + entry + png)
    print(f"wrote favicon.ico  ({len(png)}-byte PNG-32 payload, {22 + len(png)} bytes total)")

if __name__ == "__main__":
    main()
